import styled from 'styled-components'

export const Aside = styled.aside`
  padding: 16px;
  background-color: #eee;
  height: 100vh;
`
export const Filtro = styled.div`
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-gap: 8px;
  margin-top: 16px;
`

export const Opcoes = styled.div`
  margin-bottom: 16px;
  p {
    margin-bottom: 6px;
  }
  imput {
    margin-right: 6px;
  }
`
